    }
  ],
  "evidence": [
    {
      "file": "corpus/giron-d/sent/292.eml",
      "quote": "program set up for Duke deals similar to ones we have with TransCanada Energy",
      "note": "An automatic booking rule for ECC counterparties already exists for two companies, so extending it is a known change."
